-- Migración para bases creadas con el schema anterior (categoría como texto, sin historial).
-- Ejecutar una sola vez sobre una base existente:
--   psql -h localhost -U postgres -d puntopyme -f db/migrations/2026_11_04_categorias_historial_softdelete.sql

BEGIN;

CREATE TABLE IF NOT EXISTS "Categorias" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Nombre" varchar(100) NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Categorias_Nombre" ON "Categorias" ("Nombre");

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_name = 'Productos' AND column_name = 'Categoria'
  ) THEN
    INSERT INTO "Categorias" ("Nombre")
    SELECT DISTINCT TRIM("Categoria")
    FROM "Productos"
    WHERE "Categoria" IS NOT NULL AND TRIM("Categoria") <> ''
    ON CONFLICT ("Nombre") DO NOTHING;
  END IF;
END $$;

ALTER TABLE "Productos" ADD COLUMN IF NOT EXISTS "CategoriaId" integer;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_name = 'Productos' AND column_name = 'Categoria'
  ) THEN
    UPDATE "Productos" p
    SET "CategoriaId" = c."Id"
    FROM "Categorias" c
    WHERE p."CategoriaId" IS NULL
      AND p."Categoria" IS NOT NULL
      AND TRIM(p."Categoria") = c."Nombre";

    ALTER TABLE "Productos" DROP COLUMN "Categoria";
  END IF;
END $$;

ALTER TABLE "Productos" ADD COLUMN IF NOT EXISTS "Eliminado" boolean NOT NULL DEFAULT false;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'FK_Productos_Categorias_CategoriaId'
  ) THEN
    ALTER TABLE "Productos"
      ADD CONSTRAINT "FK_Productos_Categorias_CategoriaId"
      FOREIGN KEY ("CategoriaId") REFERENCES "Categorias" ("Id") ON DELETE RESTRICT;
  END IF;
END $$;

DROP INDEX IF EXISTS "IX_Productos_Sku";
CREATE UNIQUE INDEX "IX_Productos_Sku" ON "Productos" ("Sku") WHERE "Eliminado" = false;
CREATE INDEX IF NOT EXISTS "IX_Productos_CategoriaId" ON "Productos" ("CategoriaId");

CREATE TABLE IF NOT EXISTS "ProductoHistorial" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ProductoId" integer NOT NULL REFERENCES "Productos" ("Id") ON DELETE RESTRICT,
  "UsuarioId" integer NOT NULL REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT,
  "Accion" varchar(30) NOT NULL,
  "Descripcion" varchar(300) NOT NULL,
  "FechaUtc" timestamp with time zone NOT NULL,
  "StockAnterior" integer NOT NULL,
  "StockNuevo" integer NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_ProductoHistorial_ProductoId" ON "ProductoHistorial" ("ProductoId");
CREATE INDEX IF NOT EXISTS "IX_ProductoHistorial_UsuarioId" ON "ProductoHistorial" ("UsuarioId");
CREATE INDEX IF NOT EXISTS "IX_ProductoHistorial_ProductoId_FechaUtc" ON "ProductoHistorial" ("ProductoId", "FechaUtc");

COMMIT;
